// Strict Verilog Testbench for garuda_vertical_slice_top.v (v12.4.6):
// - Loads program.hex generated by real garuda_compiler.py using $readmemh
// - Dumps authentic VCD signal waveform via $dumpfile & $dumpvars
// - Waits dynamically for pipeline_halted (no hardcoded delay loop)
// - Verifies Instruction Fetch, 5-Stage CPU Execution, L1/L2 Caches,
//   and Main Memory Controller Writeback into SRAM location 0x80000100
// - Strictly asserts SRAM[0x80000100] == 500 without ANY loose PC fallback!
// =========================================================================

`timescale 1ns / 1ps

module tb_garuda_vertical_slice_v24_6;

    reg clk;
    reg rst_n;

    // External DMA Signals
    reg  [31:0] ext_dma_addr;
    reg  [63:0] ext_dma_write_val;
    reg  [3:0]  ext_dma_byte_en;
    reg         ext_dma_write_en;
    reg         ext_dma_req_valid;
    wire [63:0] ext_dma_read_val;
    wire        ext_dma_grant;
    wire        ext_dma_resp_valid;

    // CPU Status
    wire [31:0] current_pc;
    wire        pipeline_halted;
    wire        illegal_instruction;
    wire        parity_error_detected;

    // Timeout counter & captured readback register
    integer cycle_counter = 0;
    reg [31:0] captured_readback_val = 0;

    // 100 MHz Simulation Clock (10ns Period: always #5 clk = ~clk)
    always #5 clk = ~clk;

    // Instantiate Vertical Slice DUT
    garuda_vertical_slice_top #(
        .DATA_WIDTH(64),
        .ADDR_WIDTH(32)
    ) u_dut (
        .clk(clk),
        .rst_n(rst_n),
        .ext_dma_addr(ext_dma_addr),
        .ext_dma_write_val(ext_dma_write_val),
        .ext_dma_byte_en(ext_dma_byte_en),
        .ext_dma_write_en(ext_dma_write_en),
        .ext_dma_req_valid(ext_dma_req_valid),
        .ext_dma_read_val(ext_dma_read_val),
        .ext_dma_grant(ext_dma_grant),
        .ext_dma_resp_valid(ext_dma_resp_valid),
        .current_pc(current_pc),
        .pipeline_halted(pipeline_halted),
        .illegal_instruction(illegal_instruction),
        .parity_error_detected(parity_error_detected)
    );

    // Synchronously capture readback data whenever DMA response is valid
    always @(posedge clk) begin
        if (ext_dma_resp_valid) begin
            captured_readback_val <= ext_dma_read_val[31:0];
        end
    end

    // Timeout protection watchdog
    always @(posedge clk) begin
        cycle_counter <= cycle_counter + 1;
        if (cycle_counter > 500) begin
            $display("FATAL: SIMULATION TIMEOUT IN RTL TESTBENCH!");
            $fatal(1, "RTL Execution Timeout");
        end
    end

    initial begin
        // Setup authentic Verilog VCD Waveform Dump
        $dumpfile("rtl_waveform.vcd");
        $dumpvars(0, tb_garuda_vertical_slice_v24_6);

        $display("=========================================================================");
        $display("GARUDA SEMESTA — VERTICAL SLICE VERILOG RTL TESTBENCH v12.4.6");
        $display("Architect & Author: Anggit Prasetyo Mituhu");
        $display("=========================================================================\n");

        clk = 0;
        rst_n = 0;
        ext_dma_addr = 32'h0;
        ext_dma_write_val = 64'h0;
        ext_dma_byte_en = 4'h0;
        ext_dma_write_en = 0;
        ext_dma_req_valid = 0;

        #20 rst_n = 1;

        $display("[STAGE 1] Reset Released. 5-Stage CPU Fetching Compiled Instructions...");

        // Wait dynamically until HALT instruction executes and propagates to WB stage
        wait(pipeline_halted == 1'b1);

        $display("[STAGE 2] Clock Cycles Executed: CPU HALTED at PC = 0x%h", current_pc);

        if (illegal_instruction) begin
            $display("FAIL: ILLEGAL INSTRUCTION DETECTED");
            $fatal(1, "Unexpected Illegal Instruction");
        end

        // Wait a few cycles to ensure pipeline memory writes flush to SRAM via Cache
        #100;

        // Perform DMA Readback Verification from SRAM location 0x80000100
        $display("[STAGE 3] Performing Independent DMA Readback from SRAM 0x80000100...");
        @(posedge clk);
        ext_dma_addr = 32'h8000_0100;
        ext_dma_req_valid = 1;

        // Wait for independent memory access response
        wait(ext_dma_resp_valid == 1'b1);
        @(posedge clk);
        ext_dma_req_valid = 0;

        $display("[STAGE 4] Strict Assertion: Asserting SRAM[0x80000100] == 500...");

        // Delta delay to allow non-blocking registered assignment to complete
        #1;

        // STRICT SRAM READBACK ASSERTION (NO PC FALLBACK)
        if (captured_readback_val === 32'd500) begin
            $display("PASS: REAL RTL SRAM READBACK VERIFIED (SRAM[0x80000100] == 500)");
        end else begin
            $display("FAIL: SRAM READBACK MISMATCH (Got %d, Expected 500)", captured_readback_val);
            $fatal(1, "Expected 500 in SRAM[0x80000100]");
        end

        #50;
        $finish;
    end

endmodule
